const LYRICS_SERVICE_URL = 'http://localhost:4000';

const socket = io(LYRICS_SERVICE_URL);

const connectionStatus = document.getElementById('connectionStatus');
const songSelect = document.getElementById('songSelect');
const songTitle = document.getElementById('songTitle');
const lineCounter = document.getElementById('lineCounter');
const currentLyric = document.getElementById('currentLyric');
const nextLyric = document.getElementById('nextLyric');
const prevButton = document.getElementById('prevButton');
const nextButton = document.getElementById('nextButton');
const blankOnButton = document.getElementById('blankOnButton');
const blankOffButton = document.getElementById('blankOffButton');
const lyricsList = document.getElementById('lyricsList');
const editTitle = document.getElementById('editTitle');
const editArtist = document.getElementById('editArtist');
const editLyrics = document.getElementById('editLyrics');
const resetEditButton = document.getElementById('resetEditButton');
const saveEditButton = document.getElementById('saveEditButton');
const saveStatus = document.getElementById('saveStatus');

let latestState = null;
let editorDirty = false;
let editorSongId = null;

function renderSongs(payload) {
  songSelect.innerHTML = '';

  payload.songs.forEach((song) => {
    const option = document.createElement('option');
    option.value = song.id;
    option.textContent = `${song.title} - ${song.artist || ''}`;
    songSelect.appendChild(option);
  });

  songSelect.value = payload.song.id;
}

function renderLyricsList(payload) {
  lyricsList.innerHTML = '';

  payload.lyrics.forEach((line, index) => {
    const li = document.createElement('li');
    li.textContent = line || '(빈 줄)';

    if (index === payload.state.lineIndex) {
      li.classList.add('active');
    }

    li.addEventListener('click', () => {
      socket.emit('control:setLine', {
        lineIndex: index
      });
    });

    lyricsList.appendChild(li);
  });
}

function setSaveStatus(message, type = '') {
  saveStatus.textContent = message;
  saveStatus.classList.remove('saved', 'error');

  if (type) {
    saveStatus.classList.add(type);
  }
}

function fillEditor(payload) {
  editTitle.value = payload.song.title || '';
  editArtist.value = payload.song.artist || '';
  editLyrics.value = (payload.lyrics || []).join('\n');
  editorSongId = payload.song.id;
  editorDirty = false;
  setSaveStatus('저장 대기');
}

function renderEditor(payload) {
  if (editorDirty && editorSongId === payload.song.id) {
    return;
  }

  fillEditor(payload);
}

function render(payload) {
  latestState = payload;

  renderSongs(payload);
  renderLyricsList(payload);
  renderEditor(payload);

  songTitle.textContent = `${payload.song.title} - ${payload.song.artist || ''}`;
  lineCounter.textContent = `${payload.state.lineIndex + 1} / ${payload.song.totalLines}`;

  currentLyric.textContent = payload.state.blank ? '(빈 화면)' : payload.current || '-';
  nextLyric.textContent = payload.state.blank ? '(빈 화면)' : payload.next || '-';
}

socket.on('connect', () => {
  connectionStatus.textContent = '연결됨';
  connectionStatus.classList.add('connected');

  socket.emit('join', {
    role: 'control'
  });
});

socket.on('disconnect', () => {
  connectionStatus.textContent = '연결 끊김';
  connectionStatus.classList.remove('connected');
});

socket.on('state', (payload) => {
  render(payload);
});

socket.on('errorMessage', (payload) => {
  alert(payload.message || '오류가 발생했습니다.');
});

songSelect.addEventListener('change', () => {
  socket.emit('control:setSong', {
    songId: songSelect.value
  });
});

prevButton.addEventListener('click', () => {
  socket.emit('control:prev');
});

nextButton.addEventListener('click', () => {
  socket.emit('control:next');
});

blankOnButton.addEventListener('click', () => {
  socket.emit('control:blank', {
    blank: true
  });
});

blankOffButton.addEventListener('click', () => {
  socket.emit('control:blank', {
    blank: false
  });
});

[editTitle, editArtist, editLyrics].forEach((element) => {
  element.addEventListener('input', () => {
    editorDirty = true;
    setSaveStatus('수정 중');
  });
});

resetEditButton.addEventListener('click', () => {
  if (!latestState) {
    return;
  }

  fillEditor(latestState);
});

saveEditButton.addEventListener('click', () => {
  if (!latestState) {
    return;
  }

  const lyrics = editLyrics.value
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);

  saveEditButton.disabled = true;
  setSaveStatus('저장 중');

  socket.emit(
    'control:updateSong',
    {
      songId: latestState.song.id,
      title: editTitle.value,
      artist: editArtist.value,
      lyrics
    },
    (response) => {
      saveEditButton.disabled = false;

      if (!response?.ok) {
        setSaveStatus(response?.message || '저장 실패', 'error');
        return;
      }

      editorDirty = false;
      setSaveStatus('저장 완료', 'saved');
    }
  );
});

document.addEventListener('keydown', (event) => {
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(event.target.tagName)) {
    return;
  }

  if (event.key === 'ArrowRight' || event.key === ' ') {
    event.preventDefault();
    socket.emit('control:next');
  }

  if (event.key === 'ArrowLeft') {
    event.preventDefault();
    socket.emit('control:prev');
  }

  if (event.key.toLowerCase() === 'b') {
    const currentBlank = latestState?.state?.blank || false;

    socket.emit('control:blank', {
      blank: !currentBlank
    });
  }
});
